figures.script:
diagram("mode: sequence
[Application] as a
[System-call interface] as s
[File system] as f
[Buffer cache] as c
[Disk driver] as d
[Disk] as h
a -> s : read(fd, buf, 4096)
s -> f : trap into kernel
f -> c : which block holds offset 0?
c -> d : miss — fetch block 8123
d -> h : seek, rotate, transfer
h -> d : interrupt: done
d -> c : block now cached
c -> f : data
f -> a : copy 4096 bytes, return
@0 a -> s : read(fd, buf, 4096)
@1 s -> f : trap into kernel
@2 f -> c : which block holds offset 0?
@3 c -> d : miss — fetch block 8123
@4 d -> h : seek, rotate, transfer
@5.5 h -> d : interrupt: done
@6.5 d -> c : block now cached
@7.5 c -> f : data
@8.5 f -> a : copy 4096 bytes, return
loop 11");

diagram("direction: right
[User mode: application runs] as u #blue
[Kernel mode: OS runs] as k #violet
u -> k : system call, interrupt or fault (set mode bit = kernel)
k -> u : return from interrupt (set mode bit = user)
@0 u -> k : trap
@1.5 k -> u : iret
loop 3");

diagram("mode: sequence
[Running process] as p
[CPU] as c
[Interrupt vector] as v
[Handler (ISR)] as h
[Disk controller] as d
p -> c : executing instructions
d -> c : interrupt line raised
c -> c : finish current instruction, save PC and flags
c -> v : look up handler for IRQ 14
v -> h : address of disk ISR
h -> h : acknowledge device, move data
h -> c : return from interrupt
c -> p : restore PC and flags, resume
@0 p -> c : executing instructions
@1.4 d -> c : interrupt line raised
@2.4 c -> c : finish current instruction, save PC and flags
@3.4 c -> v : look up handler for IRQ 14
@4.4 v -> h : address of disk ISR
@5.4 h -> h : acknowledge device, move data
@6.4 h -> c : return from interrupt
@7.4 c -> p : restore PC and flags, resume
loop 9");

diagram("direction: right
(Power on) as a
[Firmware: BIOS / UEFI, POST] as b #amber
[Bootloader: GRUB] as c #blue
[Kernel loads, initrd] as d #violet
[init / systemd] as e #mint
(Login prompt) as f
a -> b
b -> c : find boot device, read stage 1
c -> d : load kernel + initrd, jump
d -> e : mount root, start drivers
e -> f : start services
@0 a -> b
@1 b -> c
@2 c -> d
@3 d -> e
@4 e -> f
loop 6");
